import React from "react";
import { useParams, useNavigate } from "react-router-dom";
import all_product from "../Assets/all_product";
import "./ProductDetails.css";

const ProductDetails = () => {
  const { id } = useParams();
  const navigate = useNavigate();

  // Find the product by id (id is string, convert to number if needed)
  const product = all_product.find((p) => String(p.id) === id);

  if (!product) {
    return (
      <div style={{ padding: "40px", textAlign: "center" }}>
        <h2>Product not found!</h2>
        <button onClick={() => navigate("/product")}>Back to Products</button>
      </div>
    );
  }

  return (
    <div className="product-details-container">
      <button className="back-button" onClick={() => navigate("/product")}>
        &larr; Back to Products
      </button>

      <div className="product-details-card">
        <img
          src={product.image}
          alt={product.name}
          className="product-details-image"
        />

        <div className="product-details-info">
          <h1>{product.name}</h1>
          <p className="category">Category: {product.category}</p>
          <p className="price">
            Price: ${product.new_price.toFixed(2)}{" "}
            {product.old_price && (
              <span className="old-price">${product.old_price.toFixed(2)}</span>
            )}
          </p>
          <p className="description">
            {/* Assuming you have a description field, else you can add one */}
            {product.description ||
              "No description available for this product."}
          </p>
          <button className="buy-button">Buy Now</button>
        </div>
      </div>
    </div>
  );
};

export default ProductDetails;
